
import json

def rpa_func(param):
    import re
    def bounds_to_coordinates(bounds):
        """
        将bounds字符串转换为坐标点
        code: 0:成功  1是失败  2：结束流程
        """
        numbers = list(map(int, re.findall(r'\d+', bounds)))

        # 检查是否提取到了4个数字
        if len(numbers) != 4:
            return None
        # 构建字典
        result = {
            "x1": numbers[0],
            "y1": numbers[1],
            "x2": numbers[2],
            "y2": numbers[3]
        }
        return result

    xml = param.get("xml")
    query = param.get("query")
    confirm_text = param.get("confirm_text")

    button_bounds_pattern = r'<node[^>]*text="其他车辆"[^>]*bounds="([^"]+)"'
    button_bounds_match = re.search(button_bounds_pattern, xml)
    button_bounds = button_bounds_match.group(1) if button_bounds_match else ""
    coordinates = bounds_to_coordinates(button_bounds)
    if coordinates is None:
        return {"code": 1}
    else:
        coordinates = {
            "x1": coordinates["x1"] + 5,
            "y1": coordinates["y1"] + 5,
            "x2": coordinates["x2"] - 5,
            "y2": coordinates["y2"] - 5
        }
        return {
            "code": 0,
            "thought": f"用户要更换其他车牌进行缴费，下一步应该是点击“其他车辆”这个按钮来输入车牌。",
            "actions": [{
                "action": "click",
                "name": "更换车辆",
                "coordinates": coordinates,
            }],
            "task_status": "车牌号校验"
        }

